// spec: .qa/e2e/specs/summary.md
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, endMonitoring } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(120_000);

test.describe('Сводка мониторинга', () => {
  test('Сводка со сбоем «המכשיר זז» и новая запись сверху в истории #25e8f258 @iphone @data', async ({ page }) => {
    // 1. startMonitoring(page, 'moved')
    await startMonitoring(page, 'moved');

    // 2. Дождаться сообщения сбоя «המכשיר זז»
    await expect(page.getByText('המכשיר זז').filter({ visible: true }).first()).toBeVisible({ timeout: 30_000 });

    // 3. endMonitoring (на экране сбоя — «סיום ניטור») → сводка
    await endMonitoring(page);
    await page.waitForURL(/\/monitor\/summary/, { timeout: 15_000 });

    // 4. Запомнить время начала из интервала HH:MM–HH:MM
    const interval = page.getByText(/\d{1,2}:\d{2}\s*[–-]\s*\d{1,2}:\d{2}/).filter({ visible: true }).first();
    await expect(interval).toBeVisible();
    const startTime = /(\d{1,2}:\d{2})/.exec((await interval.textContent()) ?? '')![1];

    await expect(page.getByText('תקלה אחת בניטור').filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText('כשל בניטור: המכשיר זז').filter({ visible: true })).toBeVisible();

    // 5. Нажать «לכל הניטורים»
    await page.getByRole('button', { name: 'לכל הניטורים' }).filter({ visible: true }).click();
    await page.waitForURL(/\/history/);

    // Первая (верхняя) запись истории содержит запомненное время начала
    const firstEntry = page.getByRole('button', { name: /דק׳ ניטור/ }).filter({ visible: true }).first();
    await expect(firstEntry).toBeVisible();
    await expect(firstEntry).toContainText(startTime);
  });
});
